mapper.select:
SELECT ,
       (SELECT COUNT(*) FROM wms_check_item ci WHERE ci.check_id = c.id) AS item_count,
       (SELECT COUNT(*) FROM wms_check_item ci WHERE ci.check_id = c.id
           AND ci.actual_qty IS NOT NULL AND ci.actual_qty <> ci.book_qty) AS diff_count


    c.doc_no LIKE CONCAT('%', #{q.docNo}, '%')
    AND c.warehouse_id = #{q.warehouseId}
    AND c.status = #{q.status}
    AND c.biz_date >= #{q.beginDate}
    AND c.biz_date <= #{q.endDate}

ORDER BY c.id DESC





SELECT m.id, m.code, m.name, m.spec, m.unit, m.category, m.brand, m.batch_enabled, m.serial_enabled, m.status
FROM wms_material m
WHERE m.is_template = 0

    AND (m.code LIKE CONCAT('%', #{kw}, '%') OR m.name LIKE CONCAT('%', #{kw}, '%')
         OR m.spec LIKE CONCAT('%', #{kw}, '%') OR m.barcode LIKE CONCAT('%', #{kw}, '%')
         OR m.search_key LIKE CONCAT('%', #{norm}, '%'))

AND m.category IN ()
AND m.brand = #{q.brand}
AND m.status = #{q.status}

    AND (m.default_location_id = #{q.locationId}
         OR EXISTS (SELECT 1 FROM wms_stock s WHERE s.material_id = m.id AND s.location_id = #{q.locationId} AND s.qty > 0))


    AND EXISTS (SELECT 1 FROM wms_stock s WHERE s.material_id = m.id AND s.qty > 0
                AND s.warehouse_id = #{q.warehouseId})


    AND EXISTS (SELECT 1 FROM wms_stock_flow f WHERE f.material_id = m.id
                AND f.warehouse_id = #{q.warehouseId}
                AND f.create_time >= #{changeFrom}
                AND f.create_time < #{changeTo}
                AND f.biz_type <> 'CHECK')


    AND m.id IN (SELECT i.material_id  AND d.kind = 'IN' AND d.biz_type = 'PURCHASE'
                 GROUP BY i.material_id

                     AND MAX(d.biz_date) >= #{q.purchaseBegin}
                     AND MAX(d.biz_date) <= #{q.purchaseEnd}
                 )


    AND m.id IN (SELECT i.material_id  AND d.kind = 'OUT' AND d.biz_type = 'SALES'
                 GROUP BY i.material_id

                     AND MAX(d.biz_date) >= #{q.salesBegin}
                     AND MAX(d.biz_date) <= #{q.salesEnd}
                 )

ORDER BY m.code

SELECT m.id, COALESCE(st.qty, 0) AS qty, fl.last_change_time, td.last_purchase_date, td.last_sales_date
FROM wms_material m
LEFT JOIN (SELECT s.material_id, SUM(s.qty) AS qty FROM wms_stock s
           WHERE s.material_id IN #{id}
           AND s.warehouse_id = #{warehouseId}
           GROUP BY s.material_id) st ON st.material_id = m.id
LEFT JOIN (SELECT f.material_id, MAX(f.create_time) AS last_change_time FROM wms_stock_flow f
           WHERE f.material_id IN #{id}
           AND f.warehouse_id = #{warehouseId}
           AND f.biz_type <> 'CHECK'
           GROUP BY f.material_id) fl ON fl.material_id = m.id
LEFT JOIN (SELECT i.material_id,
                  MAX(CASE WHEN d.kind = 'IN' THEN d.biz_date END) AS last_purchase_date,
                  MAX(CASE WHEN d.kind = 'OUT' THEN d.biz_date END) AS last_sales_date

           AND i.material_id IN #{id}
           AND ((d.kind = 'IN' AND d.biz_type = 'PURCHASE') OR (d.kind = 'OUT' AND d.biz_type = 'SALES'))
           GROUP BY i.material_id) td ON td.material_id = m.id
WHERE m.id IN #{id}
